{
  "items": [
    {
      "title": "GERDA: German Election Database (1945–2026)",
      "url_or_doi": "https://www.german-elections.com/",
      "justification": "One of the most comprehensive datasets for studying German elections during the 2010s and 2020s. Contains election results for federal, state, municipal, mayoral, and European Parliament elections. Provides party vote shares and election results at municipality, county, and constituency levels. Includes harmonized geographical data for longitudinal analysis. Available in CSV, Excel, and RDS formats. Particularly useful for analyzing geographical voting patterns, party competition, and electoral changes across Germany."
    },
    {
      "title": "GERDA: German Election Database – Data Downloads",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Direct dataset landing page providing downloadable German election data, including federal elections in 2013, 2017, 2021, and 2025; state elections throughout the 2010s and 2020s; and European Parliament elections in 2014, 2019, and 2024. Includes original and geographically harmonized datasets, enabling comparisons of election results across different periods and administrative boundaries."
    },
    {
      "title": "GERDA: The German Election Database – Scientific Data Publication",
      "url_or_doi": "https://doi.org/10.1038/s41597-025-04811-5",
      "justification": "Peer-reviewed scientific publication documenting the German Election Database. Describes a longitudinal dataset of German election results covering federal, state, and municipal elections, with particular emphasis on municipality-level data. Provides methodological documentation for harmonizing geographical boundaries and comparing election outcomes over time. Especially valuable for researchers requiring a documented and academically validated electoral dataset."
    },
    {
      "title": "German Federal Election 2025 – Official Open Data",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/2025/ergebnisse/opendata.html",
      "justification": "Official election dataset published by Germany's Federal Returning Officer (Die Bundeswahlleiterin). Contains results of the February 2025 Bundestag election, including votes for political parties and constituency candidates, with results available at national, state, and constituency levels. Provides machine-readable CSV and XML files, as well as constituency metadata and geographical information. Also includes access to archived 2021 election results and comparative data."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Data and Documentation",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "Major academic election research program providing survey datasets covering German federal elections in 2013, 2017, 2021, and 2025. Includes pre-election and post-election surveys, rolling cross-sectional studies, panel surveys, candidate studies, and campaign-related data. Variables cover voting behavior, party identification, political attitudes, demographic characteristics, political participation, and electoral decision-making. Particularly suitable for explaining why voters support particular parties and how their political preferences change over time."
    },
    {
      "title": "German Longitudinal Election Study (GLES) – Overview",
      "url_or_doi": "https://www.gesis.org/en/gles/overview",
      "justification": "Research dataset collection designed to support longitudinal analysis of German electoral behavior. Contains survey data collected around Bundestag elections since 2009, including the 2010s and 2020s. Supports research on political polarization, voter turnout, party identification, candidate evaluations, and changes in political attitudes. Also provides links between voter surveys and candidate-related datasets."
    },
    {
      "title": "GESIS Research Data Center – German Elections",
      "url_or_doi": "https://www.gesis.org/en/elections",
      "justification": "Comprehensive research data portal covering German federal elections, state elections, and election-related public opinion surveys. Includes the German Longitudinal Election Study, state election surveys, and recurring political opinion studies such as Politbarometer and DeutschlandTREND. Especially useful for examining voter preferences, political attitudes, and electoral trends during the 2010s and 2020s."
    },
    {
      "title": "German Longitudinal Election Study – Rolling Cross-Section Surveys 2013, 2017, 2021, and 2025",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "Collection of rolling cross-sectional surveys conducted during German federal election campaigns. Includes studies ZA5703 (2013), ZA6803 (2017), ZA7703 (2021), and ZA10101 (2025). These datasets capture changing voting intentions, candidate evaluations, political attitudes, and reactions to campaign developments. Particularly valuable for studying how electoral preferences evolve during election campaigns and how political events affect voters."
    },
    {
      "title": "German Longitudinal Election Study – Candidate Studies 2013, 2017, 2021, and 2025",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "Survey datasets examining candidates participating in German federal elections. Includes candidate studies for the 2013, 2017, 2021, and 2025 Bundestag elections. Contains information about candidates' political positions, campaign activities, backgrounds, and electoral strategies. Useful for studying political representation, candidate selection, party competition, and the relationship between political elites and voters."
    },
    {
      "title": "GLES Candidate Studies 2009, 2013, and 2017 – WZB Berlin Social Science Center",
      "url_or_doi": "https://wzb.eu/en/research/completed-research-programs/democracy-and-democratization/downloads",
      "justification": "Academic data access portal providing German election research datasets, including candidate surveys from the 2013 and 2017 Bundestag elections. Also provides access to German Longitudinal Election Study datasets and related electoral research resources. Useful for investigating candidate characteristics, campaign strategies, political representation, and differences between political parties during the 2010s."
    },
    {
      "title": "German State Elections – GESIS Research Data Collection",
      "url_or_doi": "https://www.gesis.org/en/elections",
      "justification": "Research data collection covering elections to Germany's state parliaments (Landtagswahlen). Includes state election surveys and related electoral studies from the 2010s and 2020s. Particularly useful for analyzing regional political differences, voting behavior in eastern versus western Germany, state-level party competition, and the electoral development of parties such as CDU, SPD, Greens, FDP, AfD, and Die Linke."
    },
    {
      "title": "German State Elections – GERDA Municipality-Level Results",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Detailed dataset of German state parliamentary elections, including elections held throughout the 2010s and 2020s. Provides party-level election results at municipality and constituency levels, including original and geographically harmonized observations. Particularly suitable for comparative analysis of regional electoral outcomes, geographical polarization, local party support, and changes in voting patterns between successive state elections."
    },
    {
      "title": "German European Parliament Elections 2014, 2019, and 2024 – GERDA",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Provides municipality-level results for European Parliament elections held in Germany, including 2014, 2019, and 2024. Contains party vote shares and geographically comparable electoral outcomes. Suitable for studying European election participation, euroscepticism, regional party support, and differences between European and federal election voting behavior."
    },
    {
      "title": "European Parliament Election Candidate Studies 2014 and 2024 – GLES",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "Academic survey datasets covering German candidates in European Parliament elections. Includes the 2014 European Parliament Election Study (ZA5717), the 2014 comparative candidate dataset (ZA5718), and the 2024 European Election Candidate Study (ZA7960). Useful for analyzing candidate backgrounds, political positions, party strategies, and changes in European parliamentary representation between the 2010s and 2020s."
    },
    {
      "title": "German Municipal Elections – GERDA Local Election Database",
      "url_or_doi": "https://www.german-elections.com/",
      "justification": "Longitudinal collection of German local election results covering municipal council elections during the 2010s and 2020s. Includes party vote shares at the municipality level across German states. Enables analysis of local political competition, electoral fragmentation, regional differences, and relationships between municipal, state, and national election outcomes. Particularly useful for geographically detailed political science research."
    },
    {
      "title": "German Election Results and Representative Electoral Statistics Since 1946 – Konrad Adenauer Foundation",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Historical election results collection covering German federal elections, state elections, and European Parliament elections, including those held during the 2010s and 2020s. Provides election results and representative electoral statistics for examining long-term electoral developments. Useful for comparative research on voter turnout, party vote shares, political realignment, and regional differences across election cycles."
    },
    {
      "title": "Research Data Center Elections – GESIS and KonsortSWD",
      "url_or_doi": "https://www.konsortswd.de/en/services/research/all-datacentres/fdz-wahlen/",
      "justification": "Research data infrastructure providing information about archived German federal and state election datasets. Covers voter surveys, political opinion studies, and longitudinal election research, including GLES data collected since 2009. Particularly useful for identifying additional election-related datasets, understanding data access conditions, and locating specialized studies on voting behavior and political attitudes during the 2010s and 2020s."
    }
  ]
}
